	aliases = { "Garran Vimes", "Capitão Vimes" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Capitão Garran Vimes comanda a guarda de {link:theramore-isle}Theramore{/link} do último andar da Cidadela do Esteio. Todo relatório do pântano chega à sua mesa: espiões nos juncos, desertores nas torres, uma estalagem queimada na estrada do oeste. Ele lê {link:orcs}orc{/link} melhor do que a maioria dos homens da cidade e confia mais em fatos do que em boatos. Não tem soldados suficientes, e diz isso com franqueza.]=],
		},
