Translate("ptBR", "overlord-mok-morokk", {
	title = "Suserano Mok'Morokk",
	subtitle = "Suserano dos Pedramalho",
	found = "Aldeia Muralha Verde",
	hint = [=[Curve-se diante do suserano dos Pedramalho na Aldeia Muralha Verde.]=],
	allegiance = "Ogros Pedramalho · Horda",
	aliases = { "Mok'Morokk" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Suserano Mok'Morokk governa os {red:stonemaul-ogres}ogros Pedramalho{/red} a partir da {link:brackenwall-village}Aldeia Muralha Verde{/link}. {link:rexxar}Rexxar{/link} o fez suserano, e Mok'Morokk nunca deixa ninguém esquecer disso. Quando dragões negros incendiaram a aldeia Pedramalho no sul, ele guiou seu povo para o norte, até os juncos. Ele chama isso de sabedoria. Muitos de seus ogros chamam de fuga.]=],
		},
		{
			title = "Importância",
			text = [=[Mok'Morokk mostra o que o poder pode fazer a um líder que ninguém vigia. Era forte enquanto {link:rexxar}Rexxar{/link} liderava o clã. Depois que Rexxar partiu, passou a exigir serviço em vez de prestá-lo, e seu povo começou a se voltar contra ele.]=],
		},
		{
			title = "Feitos",
			text = [=[• Tirou os Pedramalho de sua antiga aldeia quando os dragões negros chegaram.
• Mandou outros de volta às ruínas atrás do grogue, do rapé e do cofre que deixara para trás.
• Recusou-se a pegar em armas contra a ninhada de {link:onyxia}Onyxia{/link}.]=],
		},
	},
	chapters = {
		{
			title = "As Coisas do Suserano",
			hint = "Recupere o que o suserano deixou para trás no sul.",
			text = [=[Mok'Morokk deixou seu lar com tanta pressa que esqueceu as coisas de que mais gostava. Não voltou ele mesmo para buscá-las. Estava ocupado demais liderando, disse. Então outros foram para o sul, ao fogo das {link:stonemaul-ruins}Ruínas Pedramalho{/link} e do Antro das Chamas, e trouxeram de volta seu grogue, seu rapé e sua caixa de tesouros.]=],
		},
		{
			title = "O Desafio",
			hint = "Desafie o suserano em sua própria aldeia.",
			text = [=[{link:draz-zilb}Draz'Zilb{/link} decidira que o clã precisava de um novo líder. Quando o suserano foi desafiado em {link:brackenwall-village}Muralha Verde{/link}, riu e prometeu uma surra. Perdeu. O poderoso suserano dos Pedramalho fugiu de sua própria aldeia como uma criança assustada, e os ogros começaram a falar em escolher um líder que os levasse para casa.]=],
		},
	},
	mentions = {
		{ text = "Overlord Mok'Morokk's Concern" },
		{ text = "The Brood of {link:onyxia}Onyxia{/link}" },
		{ text = "The Brood of {link:onyxia}Onyxia{/link}" },
		{ text = "Challenge Overlord Mok'Morokk" },
	},
	bonds = {
